procedure @@proc@@(p_id in number) is
  l_rows number;
begin
  update @@tab@@
     set @@col@@ = sysdate
   where id = p_id;
  l_rows := sql%rowcount;
  dbms_output.put_line('rows touched: ' || l_rows);
exception
  when others then null; -- @expect
end @@proc@@;

function @@proc@@(p_key in varchar2) return number is
  l_total number := 0;
begin
  select count(*)
    into l_total
    from @@tab@@
   where @@col@@ = p_key;
  return l_total;
exception
  when others then -- @expect
    return 0;
end @@proc@@;

procedure @@proc@@(p_id in number, p_status out varchar2) is
begin
  p_status := 'done';
  delete from @@tab@@
   where id = p_id;
exception
  when others then -- @expect
    p_status := 'failed';
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_next number;
begin
  l_next := p_id + 1;
  @@proc2@@(l_next);
  dbms_output.put_line('step completed');
exception
  when others then -- @expect
    dbms_output.put_line('step failed');
end @@proc@@;

procedure @@proc@@(p_ids in dbms_sql.number_table) is
begin
  for i in 1 .. p_ids.count loop
    begin
      @@proc2@@(p_ids(i));
    exception
      when others then null; -- @expect
    end;
  end loop;
end @@proc@@;

