procedure @@proc@@(p_id in number) is
  l_stage varchar2(30);
begin
  l_stage := 'load';
  @@proc2@@(p_id);
  l_stage := 'post';
  @@proc2@@(p_id + 1);
exception
  when others then
    rollback;
    raise;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_ok boolean := true;
begin
  update @@tab@@
     set @@col@@ = @@col@@ + 1
   where id = p_id;
exception
  when others then
    logger.log_error('update failed for ' || p_id);
    l_ok := false;
end @@proc@@;

procedure @@proc@@(p_id in number, p_err out varchar2) is
begin
  p_err := null;
  @@proc2@@(p_id);
exception
  when others then
    p_err := sqlerrm;
end @@proc@@;

procedure @@proc@@(p_id in number) is
  l_copy number;
begin
  l_copy := p_id;
  @@proc2@@(l_copy);
exception
  when others then
    raise_application_error(-20010, 'processing failed for id ' || p_id);
end @@proc@@;

procedure @@proc@@(p_id in number, p_name out varchar2) is
begin
  begin
    select @@col@@
      into p_name
      from @@tab@@
     where id = p_id;
  exception
    when no_data_found then null;
  end;
  p_name := upper(p_name);
end @@proc@@;
